// Bench roster visual baselines (#437): every viewport × theme project (360/768/1280, light and
// dark) with the clock frozen: the rosters list (versions, the roster in force, halls and alerts),
// the bench-change banner on its own, the import review of fixtures/roster-pdf.ts (a row to check
// and the sticky summary) and the empty list. Baselines live in e2e/__screenshots__ and are only
// ever generated by the e2e workflow's `update_snapshots` dispatch in the pinned Playwright image
// (see e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { expect, test } from '../../fixtures/index.ts';
import { ROSTER_FORUM } from '../../fixtures/courts-data.ts';

import {
  emptyRosters,
  openCourts,
  rosterImportPath,
  rostersPath,
  uploadRosterPdf,
} from './helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  /** `database` is the worker database. Returns the element to shoot, or the page. */
  setUp: (page: Page, asUser: AsUser, database: string) => Promise<Locator | null>;
}

const SHOTS: readonly Shot[] = [
  {
    name: 'rosters-list.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser, { path: rostersPath(ROSTER_FORUM.code) });
      await expect(page.locator('[data-roster-active-today]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'rosters-alert-banner.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser, { path: rostersPath(ROSTER_FORUM.code) });
      return page.locator('[data-slot="bench-change-banner"]');
    },
  },
  {
    name: 'rosters-import-review.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser, { path: rosterImportPath(ROSTER_FORUM.code) });
      await uploadRosterPdf(page);
      return null;
    },
  },
  {
    name: 'rosters-empty.png',
    setUp: async (page, asUser, database) => {
      await emptyRosters(database);
      await openCourts(page, asUser, { path: rostersPath() });
      await expect(page.locator('main [data-pattern-state="empty"]')).toBeVisible();
      return null;
    },
  },
];

test.describe('rosters visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        const target = await shot.setUp(page, asUser, db.name);
        const options = { animations: 'disabled', caret: 'hide' } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
